<script setup lang="ts">
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value))
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { request, latestRequest } from '../api'
import { color, fmt, money, pct, signed, timeText, modeNames } from '../format'
import type { Page, Snapshot, Mode } from '../types'
import type { ResearchRun, StrategyCatalog, StrategySetting } from '../research-types'
import StrategyEditor from './StrategyEditor.vue'
import EquityChart from './EquityChart.vue'
import Pagination from './Pagination.vue'
const props=defineProps<{snapshot:Snapshot|null;active:boolean}>()
const catalog=ref<StrategyCatalog|null>(null), strategies=ref<Record<string,StrategySetting>>({})
const form=reactive({name:'',mode:'demo' as Mode,codes:'',start_date:'',end_date:'',initial_cash:100000,max_positions:3,position_pct:30,slippage_bps:5,strategy_id:'teaching',stop_loss_pct:5,take_profit_pct:10,max_holding_days:20,commission_rate:.0003,minimum_commission:5,stamp_tax_rate:.0005})
const dirty=ref(false),busy=ref(false),error=ref(''),feedback=ref(''),listBusy=ref(false),detailBusy=ref(false)
const runs=ref<Page<ResearchRun>>({items:[],total:0,page:1,pages:1,page_size:30}), detail=ref<ResearchRun|null>(null),selected=ref<(string|number)[]>([]),comparison=ref<ResearchRun[]>([]),comparisonBusy=ref(false)
const tradePage=ref(1), signalPage=ref(1),rejectPage=ref(1)
const generation=latestRequest(),detailGeneration=latestRequest();let pollTimer:ReturnType<typeof setTimeout>|undefined;let disposed=false
const report=computed(()=>detail.value?.report)
const detailMetrics=computed(()=>report.value?.metrics)
const tradeSlice=computed(()=>(report.value?.trades??[]).slice((tradePage.value-1)*30,tradePage.value*30))
const signalSlice=computed(()=>(report.value?.signals??[]).slice((signalPage.value-1)*30,signalPage.value*30))
const rejectSlice=computed(()=>(report.value?.rejections??[]).slice((rejectPage.value-1)*30,rejectPage.value*30))
const pages=(count:number)=>Math.max(1,Math.ceil(count/30))
watch(()=>props.snapshot,s=>{if(s&&!dirty.value&&!form.codes){form.codes=s.settings.watchlist.join(', ');form.mode=s.settings.mode;strategies.value=clone((s.settings.strategy_config??catalog.value?.defaults??{}) as Record<string,StrategySetting>) }},{immediate:true})
async function getCatalog(){if(catalog.value)return;try{catalog.value=await request<StrategyCatalog>('/api/strategies');if(!Object.keys(strategies.value).length)strategies.value=clone(catalog.value.defaults)}catch(e){error.value=e instanceof Error?e.message:String(e)}}
async function load(page=runs.value.page){const id=generation.next();listBusy.value=true;try{const result=await request<Page<ResearchRun>>(`/api/research?page=${page}`);if(generation.current(id)){runs.value=result}}catch(e){if(generation.current(id))error.value=e instanceof Error?e.message:String(e)}finally{if(generation.current(id))listBusy.value=false}}
async function open(id:number|string){const generation=detailGeneration.next();detailBusy.value=true;try{const result=await request<ResearchRun>(`/api/research/${id}`);if(detailGeneration.current(generation)){const changed=detail.value?.id!==id;detail.value=result;if(changed){tradePage.value=1;signalPage.value=1;rejectPage.value=1}}}catch(e){if(detailGeneration.current(generation))error.value=e instanceof Error?e.message:String(e)}finally{if(detailGeneration.current(generation))detailBusy.value=false}}
async function cycle(){clearTimeout(pollTimer);if(!props.active||disposed)return;await load();if(detail.value?.status==='running')await open(detail.value.id);if(!disposed&&props.active)pollTimer=setTimeout(cycle,runs.value.items.some(r=>r.status==='running')?2000:15000)}
watch(()=>props.active,active=>{if(active){void getCatalog();void cycle()}else clearTimeout(pollTimer)},{immediate:true})
onBeforeUnmount(()=>{disposed=true;clearTimeout(pollTimer);generation.invalidate();detailGeneration.invalidate()})
async function start(){if(busy.value||!props.snapshot?.csrf_token)return;error.value='';feedback.value='';const codes=[...new Set(form.codes.split(/[\s,，;；]+/).filter(Boolean))];if(!codes.length||codes.length>50||codes.some(c=>!/^\d{6}$/.test(c))){error.value='请选择 1–50 只六位股票代码。';return}if(form.start_date&&form.end_date&&form.start_date>form.end_date){error.value='开始日期不能晚于结束日期。';return}if(!strategies.value[form.strategy_id]?.enabled){error.value='当前回放策略已关闭，请启用后再创建实验。';return}busy.value=true;try{const result=await request<ResearchRun>('/api/research',{...form,name:form.name.trim()||`${catalog.value?.strategies.find(s=>s.id===form.strategy_id)?.name??'研究'} · ${modeNames[form.mode]}`,codes,strategies:strategies.value},props.snapshot.csrf_token);feedback.value='回放任务已创建，后台完成后会自动显示报告。';await load(1);await open(result.id);clearTimeout(pollTimer);pollTimer=setTimeout(cycle,1500)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function archive(item:ResearchRun){if(busy.value||!props.snapshot?.csrf_token||item.status==='running')return;busy.value=true;try{await request(`/api/research/${item.id}/archive`,{},props.snapshot.csrf_token);if(detail.value?.id===item.id)await open(item.id);await load();feedback.value='实验已归档，历史报告仍可查看。'}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function compare(){if(comparisonBusy.value||selected.value.length<2)return;comparisonBusy.value=true;try{comparison.value=await Promise.all(selected.value.map(id=>request<ResearchRun>(`/api/research/${id}`)));feedback.value='比较时请保持数据来源、股票池、日期及费用一致；不同区间的收益不可直接排名。'}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{comparisonBusy.value=false}}
function toggle(id:number|string){selected.value=selected.value.includes(id)?selected.value.filter(i=>i!==id):selected.value.length<5?[...selected.value,id]:selected.value}
function reuse(item:ResearchRun){const cfg=item.config;for(const key of Object.keys(form) as (keyof typeof form)[]){if(key in cfg)(form as unknown as Record<string,unknown>)[key]=clone(cfg[key])}if(Array.isArray(cfg.codes))form.codes=cfg.codes.join(', ');if(cfg.strategies)strategies.value=clone(cfg.strategies as Record<string,StrategySetting>);form.name=`${item.name} · 对照`;dirty.value=true;feedback.value='已载入此实验参数。调整后启动，结果将独立保存。'}
const statusName=(status:string)=>({running:'运行中',completed:'已完成',failed:'失败'}[status]??status)
</script>
<template><section class="view" aria-label="策略回放"><div class="page-heading"><div><div class="eyebrow">STRATEGY RESEARCH & REPLAY</div><h1>让策略接受历史检验<span class="heading-dot">.</span></h1><p>完整链路：历史日线 → 条件信号 → 下一交易日模拟成交 → 费用、收益与回撤。不会连接券商或改动手动账本。</p></div></div><div v-if="error" class="error-banner" role="alert">{{ error }}</div><p v-if="feedback" class="inline-feedback" role="status">{{ feedback }}</p>
<div class="research-setup-grid"><section class="panel"><div class="panel-heading"><h2>新建策略实验</h2><span class="badge neutral">后台任务 · 独立账户</span></div><form class="panel-body" @submit.prevent="start" @input="dirty=true" @change="dirty=true"><fieldset :disabled="busy||!snapshot||!catalog"><div class="form-row"><label>实验名称<input v-model="form.name" maxlength="60" placeholder="例如：趋势回调对照"></label><label>历史数据<select v-model="form.mode"><option value="demo">合成演示（不代表实际业绩）</option><option value="eastmoney">公开真实历史日线</option><option value="csv">已导入 CSV 日线</option></select></label></div><label>股票代码（最多 50 只）<textarea v-model="form.codes" rows="2" placeholder="600036, 000333" required></textarea></label><div class="form-row"><label>开始日期（可留空）<input v-model="form.start_date" type="date" min="2025-01-02" max="2026-12-31"></label><label>结束日期（可留空）<input v-model="form.end_date" type="date" min="2025-01-02" max="2026-12-31"></label></div><p class="form-help">留空自动使用数据可用区间，指标先预热至少 60 根。无数据或预热不足直接报告，不会替换为合成行情。</p><div class="parameter-grid"><label>初始资金（元）<input v-model.number="form.initial_cash" type="number" min="100" max="100000000" step=".01" required></label><label>同时最多持仓<input v-model.number="form.max_positions" type="number" min="1" max="50" required></label><label>单仓资金比例（%）<input v-model.number="form.position_pct" type="number" min="1" max="100" required></label><label>每边不利滑点（bps）<input v-model.number="form.slippage_bps" type="number" min="0" max="200" required></label></div><label>本实验策略<select v-model="form.strategy_id"><option v-for="strategy in catalog?.strategies??[]" :key="strategy.id" :value="strategy.id">{{ strategy.name }}</option></select></label><details class="parameter-details"><summary>策略判断参数</summary><StrategyEditor v-model="strategies" :catalog="catalog" :disabled="busy"/></details><details class="parameter-details"><summary>退出规则与费率</summary><div class="parameter-grid"><label>止损距离（%）<input v-model.number="form.stop_loss_pct" type="number" min=".1" max="50" step=".1" required></label><label>止盈距离（%）<input v-model.number="form.take_profit_pct" type="number" min=".1" max="100" step=".1" required></label><label>最长持有交易日<input v-model.number="form.max_holding_days" type="number" min="1" max="250" required></label><label>佣金率<input v-model.number="form.commission_rate" type="number" min="0" max=".02" step=".00001" required></label><label>最低每笔佣金（元）<input v-model.number="form.minimum_commission" type="number" min="0" max="100" step=".1" required></label><label>卖出印花税率<input v-model.number="form.stamp_tax_rate" type="number" min="0" max=".02" step=".0001" required></label></div></details><button class="button primary full" type="submit">{{ busy?'提交中…':'启动历史回放' }}</button></fieldset></form></section>
<section class="panel"><div class="panel-heading"><div><h2>实验记录与比较</h2><p>同区间、同股票池、同费用比较更有意义</p></div><button class="cancel-order" :disabled="listBusy" @click="load()">刷新</button></div><div class="table-wrap"><table><thead><tr><th>对照</th><th>实验 / 时间</th><th>状态</th><th class="num">净收益率</th><th></th></tr></thead><tbody><tr v-for="item in runs.items" :key="item.id" :class="{selected:detail?.id===item.id}"><td><input type="checkbox" :checked="selected.includes(item.id)" :disabled="item.status!=='completed'||(!selected.includes(item.id)&&selected.length>=5)" :aria-label="`比较${item.name}`" @change="toggle(item.id)"></td><td>{{ item.name }}<span class="stock-code">{{ modeNames[item.config.mode as Mode]??item.config.mode }} · {{ timeText(item.created_at) }}{{ item.archived?' · 已归档':'' }}</span></td><td><span class="badge" :class="item.quality==='invalid_corporate_actions'?'unavailable':item.status==='completed'?'watch':item.status==='failed'?'unavailable':'wait'">{{ item.quality==='invalid_corporate_actions'?'结果失真':statusName(item.status) }}</span></td><td class="num" :class="item.quality==='invalid_corporate_actions'?'muted':color(item.metrics?.total_return_pct)">{{ item.quality==='invalid_corporate_actions'?'不可用于业绩评估':pct(item.metrics?.total_return_pct) }}</td><td><button class="cancel-order" :disabled="detailBusy" @click="open(item.id)">报告</button></td></tr><tr v-if="!runs.items.length"><td colspan="5" class="empty">{{ listBusy?'正在加载…':'暂无实验。创建回放后会在这里保存完整结果。' }}</td></tr></tbody></table></div><div class="panel-footer"><span>共 {{ runs.total }} 项</span><Pagination :page="runs.page" :pages="runs.pages" :busy="listBusy" label="策略实验分页" @change="load"/></div><div class="panel-body"><button class="button secondary" :disabled="selected.length<2||comparisonBusy" @click="compare">{{ comparisonBusy?'加载对照…':`比较所选（${selected.length}/5）` }}</button><p class="form-help">至少选择 2 个已完成报告。不同参数运行会创建新的实验，不覆盖旧报告。</p><dl class="rule-list"><div><dt>数据与成交分离</dt><dd>收盘信号在之后的开盘尝试执行，避免使用未来数据。遵循 T+1、板块申报、涨跌停、停牌、费用和资金限制。</dd></div><div><dt>实际可成交性仍有边界</dt><dd>日线无法还原盘口与排队；使用保守滑点假设。未平仓市值属于浮动结果，历史盈利不代表未来收益。</dd></div><div><dt>基准含义</dt><dd>比较同一研究股票池的等权持有表现，不冒充宽基指数；细节见报告假设。</dd></div></dl></div></section></div>
<section v-if="comparison.length" class="panel block-panel"><div class="panel-heading"><h2>实验对照</h2><button class="cancel-order" @click="comparison=[]">收起</button></div><div class="table-wrap"><table><thead><tr><th>实验</th><th>来源 / 日期 / 策略</th><th class="num">净收益率</th><th class="num">基准</th><th class="num">最大回撤</th><th class="num">已平仓 / 胜率</th><th class="num">费用</th></tr></thead><tbody><tr v-for="item in comparison" :key="item.id"><td>{{ item.name }}<span v-if="item.report?.quality==='invalid_corporate_actions'" class="stock-code error">报告存在公司行动偏差，不可作为有效业绩</span></td><td>{{ modeNames[item.config.mode as Mode]??item.config.mode }} · {{ item.report?.config.start_date }} — {{ item.report?.config.end_date }}<span class="stock-code">{{ item.report?.config.strategy_id }} · {{ (item.config.codes as string[])?.join(', ') }}</span></td><td class="num" :class="item.report?.quality==='invalid_corporate_actions'?'muted':color(item.report?.metrics.total_return_pct)">{{ item.report?.quality==='invalid_corporate_actions'?'不可比较业绩':pct(item.report?.metrics.total_return_pct) }}</td><td class="num">{{ pct(item.report?.metrics.benchmark_return_pct) }}</td><td class="num">{{ fmt(item.report?.metrics.max_drawdown_pct) }}%</td><td class="num">{{ fmt(item.report?.metrics.closed_trade_count,0) }} / {{ item.report?.metrics.win_rate_pct==null?'暂无平仓样本':fmt(item.report.metrics.win_rate_pct)+'%' }}</td><td class="num">{{ money(item.report?.metrics.total_fees) }}</td></tr></tbody></table></div></section>
<section v-if="detail" class="panel block-panel research-report" aria-label="历史回放报告"><div class="panel-heading"><div><h2>{{ detail.name }}</h2><p>{{ modeNames[detail.config.mode as Mode]??detail.config.mode }} · {{ statusName(detail.status) }} · {{ timeText(detail.created_at) }} · {{ detail.archived?'已归档':'独立研究实验' }}</p></div><div class="action-row"><button class="cancel-order" @click="reuse(detail)">载入参数作对照</button><button v-if="!detail.archived" class="cancel-order" :disabled="busy||detail.status==='running'" @click="archive(detail)">归档报告</button></div></div><p v-if="detail.status==='running'" class="empty">正在采集和回放，报告完成后自动显示。你可以切换其他页面。</p><div v-if="detail.error" class="error-banner">{{ detail.error }}</div><template v-if="report"><div class="report-source notice" :class="{live: detail.config.mode!=='demo'}"><strong>{{ detail.config.mode==='demo'?'合成实验 · 不代表实际业绩':detail.config.mode==='csv'?'本地 CSV 历史回放':'公开真实日线回放' }}</strong><span>{{ report.source||'来源以本实验配置与数据指纹为准' }}</span></div><div v-if="report.quality==='invalid_corporate_actions'" class="error-banner">报告无效：区间存在公司行动，当前模拟未完整处理权益调整，以下收益与回撤不能作为有效业绩。</div><div class="report-metrics"><article><span>净收益率</span><strong :class="color(detailMetrics?.total_return_pct)">{{ pct(detailMetrics?.total_return_pct) }}</strong></article><article><span>最大回撤</span><strong>{{ fmt(detailMetrics?.max_drawdown_pct) }}%</strong></article><article><span>期末净资产</span><strong>{{ money(detailMetrics?.final_equity) }}</strong></article><article><span>成交笔数 / 平仓</span><strong>{{ detailMetrics?.trade_count }} / {{ detailMetrics?.closed_trade_count }}</strong></article><article><span>已平仓胜率</span><strong>{{ detailMetrics?.win_rate_pct==null?'暂无平仓':fmt(detailMetrics.win_rate_pct)+'%' }}</strong></article><article><span>总费用</span><strong>{{ money(detailMetrics?.total_fees) }}</strong></article><article><span>股票池基准收益</span><strong>{{ pct(detailMetrics?.benchmark_return_pct) }}</strong></article><article><span>初始资金</span><strong>{{ money(detailMetrics?.initial_cash) }}</strong></article></div><EquityChart :points="report.equity_curve"/><div class="panel-body"><div v-for="warning in report.warnings" :key="warning" class="notice report-warning">{{ warning }}</div><details open><summary>回放假设与数据质量</summary><ul><li v-for="assumption in report.assumptions" :key="assumption">{{ assumption }}</li></ul><p v-if="report.excluded.length">未纳入回放：</p><ul><li v-for="excluded in report.excluded" :key="excluded.code">{{ excluded.code }} {{ excluded.name }}：{{ excluded.reason }}</li></ul></details><details><summary>可复现参数、版本与数据指纹</summary><p>回放版本 {{ report.version }} · 策略版本 {{ report.strategy_version??'—' }} · 指纹 {{ report.data_fingerprint }}</p><pre>{{ JSON.stringify({data:detail.config,parameters:report.config},null,2) }}</pre></details></div>
<h3 class="table-title">实际模拟成交 <span class="muted">买入盈亏留空；卖出显示扣除买卖费用后的净已实现结果</span></h3><div class="table-wrap"><table><thead><tr><th>成交 / 信号日</th><th>股票</th><th>方向</th><th class="num">股数</th><th class="num">成交价</th><th class="num">费用</th><th class="num">净已实现</th><th>原因</th></tr></thead><tbody><tr v-for="(t,i) in tradeSlice" :key="i"><td>{{ t.date }}<span class="stock-code">信号 {{ t.signal_date }}</span></td><td>{{ t.name }}<span class="stock-code">{{ t.code }}</span></td><td :class="t.side==='buy'?'up':'down'">{{ t.side==='buy'?'买入':'卖出' }}</td><td class="num">{{ fmt(t.quantity,0) }}</td><td class="num">{{ money(t.price) }}</td><td class="num">{{ money(t.fee) }}</td><td class="num" :class="color(t.realized_pnl)">{{ signed(t.realized_pnl) }}</td><td class="order-note">{{ t.reason }}</td></tr><tr v-if="!tradeSlice.length"><td colspan="8" class="empty">没有模拟成交。请查看信号与未成交原因，系统不会为了填充结果而强制买入。</td></tr></tbody></table></div><div class="panel-footer"><span>共 {{ report.trades.length }} 笔 · 每页 30 条</span><Pagination :page="tradePage" :pages="pages(report.trades.length)" label="回放成交分页" @change="tradePage=$event"/></div>
<details class="report-section"><summary>期末仍持有（{{ report.positions.length }}）</summary><div class="table-wrap"><table><thead><tr><th>股票</th><th>入场日</th><th class="num">数量</th><th class="num">成本 / 现价</th><th class="num">市值</th><th class="num">浮动收益</th></tr></thead><tbody><tr v-for="p in report.positions" :key="p.code"><td>{{ p.name }} {{ p.code }}</td><td>{{ p.entry_date }}</td><td class="num">{{ fmt(p.quantity,0) }}</td><td class="num">{{ money(p.entry_price) }} / {{ money(p.last_price) }}</td><td class="num">{{ money(p.market_value) }}</td><td class="num" :class="color(p.unrealized_pnl)">{{ signed(p.unrealized_pnl) }}</td></tr></tbody></table></div></details>
<details class="report-section"><summary>未成交 / 拒绝原因（{{ report.rejections.length }}）</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>股票</th><th>方向</th><th>原因</th></tr></thead><tbody><tr v-for="(item,i) in rejectSlice" :key="i"><td>{{ item.date }}</td><td>{{ item.code }}</td><td>{{ item.side==='buy'?'买':'卖' }}</td><td>{{ item.reason }}</td></tr></tbody></table></div><Pagination :page="rejectPage" :pages="pages(report.rejections.length)" label="回放拒绝分页" @change="rejectPage=$event"/></details>
<details class="report-section"><summary>形成的策略信号（{{ report.signals.length }}）</summary><div class="table-wrap"><table><thead><tr><th>日期</th><th>股票</th><th>策略</th><th>评分</th></tr></thead><tbody><tr v-for="(item,i) in signalSlice" :key="i"><td>{{ item.date }}</td><td>{{ item.code }}</td><td>{{ item.strategy_id }}</td><td>{{ item.score }}</td></tr></tbody></table></div><Pagination :page="signalPage" :pages="pages(report.signals.length)" label="回放信号分页" @change="signalPage=$event"/></details>
</template></section></section></template>
